INSERT INTO "Projects" ("Id","Title","Blurb","Year","Role","Link","Repo","Tech") VALUES ('enterprise-integration-automation','Enterprise Integration & Automation','Led the QTS platform''s Azure modernization and built the integration layer around it: OAuth and Azure-token REST APIs, ServiceNow catalog automation for thousands of users, and scheduled workflows for licensing, DFS archiving and data normalization. The automation removed hundreds of administrative hours a year and replaced hand-run processes with documented, supported services.',2025,'Integration & Automation Architect · Burns & McDonnell',NULL,NULL,'["Azure","ServiceNow","REST / OAuth",".NET","PowerShell","IBM i","Data governance"]')
  ON CONFLICT ("Id") DO UPDATE SET "Title"=excluded."Title","Blurb"=excluded."Blurb","Year"=excluded."Year","Role"=excluded."Role","Link"=excluded."Link","Tech"=excluded."Tech";
INSERT INTO "Projects" ("Id","Title","Blurb","Year","Role","Link","Repo","Tech") VALUES ('ibmi-azure-integration-bridge','IBM i ↔ Azure Integration Bridge','Design and maintain the bridge between IBM i (RPGLE/CL) business systems and Azure-hosted Python and .NET services. Work with stakeholders to define interfaces, replace manual workflows with supported automation, and keep production integrations observable and recoverable.',2026,'Integration Architect / Programmer-Analyst · Murphy-Hoffman',NULL,NULL,'["IBM i","RPGLE","CL","Azure","Python",".NET","REST APIs"]')
  ON CONFLICT ("Id") DO UPDATE SET "Title"=excluded."Title","Blurb"=excluded."Blurb","Year"=excluded."Year","Role"=excluded."Role","Link"=excluded."Link","Tech"=excluded."Tech";
INSERT INTO "Projects" ("Id","Title","Blurb","Year","Role","Link","Repo","Tech") VALUES ('op-e-console-secure-term','OP-E Console & Secure-Term','Designed and operate an end-to-end encrypted AI operations console and browser terminal. TypeScript/React front end, Python services, AES-GCM/WebCrypto, SSH into persistent tmux sessions, cost analytics, monitoring, recall, model routing and a supervised remote-desktop gateway, deployed behind Cloudflare Access with backups and recovery runbooks.',2026,'AI Systems Architect · Independent',NULL,NULL,'["TypeScript","React","Python","AES-GCM","WebCrypto","SSH / tmux","Docker","Cloudflare Access","LLMs"]')
  ON CONFLICT ("Id") DO UPDATE SET "Title"=excluded."Title","Blurb"=excluded."Blurb","Year"=excluded."Year","Role"=excluded."Role","Link"=excluded."Link","Tech"=excluded."Tech";
INSERT INTO "Projects" ("Id","Title","Blurb","Year","Role","Link","Repo","Tech") VALUES ('career-automation-stack','Career Automation Stack','Self-hosted job and contract pipeline built on n8n, NocoDB/PostgreSQL and FastAPI. Scores roles against an evidence-based skill inventory, generates ATS-safe resumes, and runs the work as background jobs, with a human in control of every application.',2026,'Automation Architect · Independent','/projects/jobdashboard',NULL,'["n8n","NocoDB","PostgreSQL","FastAPI","Python","LLM","Docker"]')
  ON CONFLICT ("Id") DO UPDATE SET "Title"=excluded."Title","Blurb"=excluded."Blurb","Year"=excluded."Year","Role"=excluded."Role","Link"=excluded."Link","Tech"=excluded."Tech";
INSERT INTO "Projects" ("Id","Title","Blurb","Year","Role","Link","Repo","Tech") VALUES ('agent-test-command-deck','Agent-Test & Command Deck','Disposable-container CI harness for static, unit/API/UI and hardcoded-value checks, plus a config-driven Docker control plane with health probes, guarded actions and Cloudflare Access. Built so agent-generated and human changes pass the same verification gate.',2026,'Platform & Verification Architect · Independent',NULL,NULL,'["Docker","pytest","Browserless","FastAPI","Docker SDK","Cloudflare Access","CI/CD"]')
  ON CONFLICT ("Id") DO UPDATE SET "Title"=excluded."Title","Blurb"=excluded."Blurb","Year"=excluded."Year","Role"=excluded."Role","Link"=excluded."Link","Tech"=excluded."Tech";
INSERT INTO "Projects" ("Id","Title","Blurb","Year","Role","Link","Repo","Tech") VALUES ('zero-trust-platform','Zero Trust Self-Hosted Platform','Self-hosted Linux and Docker platform published only through Cloudflare Zero Trust tunnels, with identity-aware access, monitoring, alerting, backups and disaster-recovery runbooks. Designed to fail visibly and recover without manual babysitting.',2026,'Platform Architect · Independent',NULL,NULL,'["Linux","Docker","Cloudflare Zero Trust","Monitoring","Backups / DR","Networking"]')
  ON CONFLICT ("Id") DO UPDATE SET "Title"=excluded."Title","Blurb"=excluded."Blurb","Year"=excluded."Year","Role"=excluded."Role","Link"=excluded."Link","Tech"=excluded."Tech";
INSERT INTO "Projects" ("Id","Title","Blurb","Year","Role","Link","Repo","Tech") VALUES ('local-ai-deliberation','Local AI Deliberation Council','Multi-agent deliberation system where local models answer independently, cross-examine blind-labelled rounds and a separate judge reads the verdict. Runs entirely on owned hardware via Ollama, with structured outputs and no data leaving the network.',2026,'AI Systems Architect · Independent','/projects/ouroborn',NULL,'["Python","Ollama","LLM","Multi-agent systems","FastAPI","SQLite"]')
